// Lab 23.1: what runStaged and runInFlight receive, and the provided pieces each
// backend implements. Provided; you do not edit this file.
//
// The job is the chapter 2 round trip, split up: n floats in host memory go to
// the device, an elementwise kernel turns each one into its output, and n
// floats come back to host memory. The kernel evaluates a polynomial of degree
// `degree` by Horner's rule, so its cost per element can be dialled to match the
// copies. Neither the kernel nor the experiment is in the book: section 23.3
// (pp. 553-563) overlaps a halo exchange with a kernel, and this lab applies the
// same tools (streams, cudaMemcpyAsync, pinned memory) to copies over the
// host-device link, the pattern NVIDIA's Best Practices Guide prints
// (notes/today/ch23-facts.md A7).
//
// The chunks. Both runStaged and runInFlight split the n elements into
// `chunks` contiguous chunks: chunk k is [k*n/chunks, (k+1)*n/chunks), integer
// division, computed without overflow. Some chunks are empty when n < chunks;
// skip them. Number the chunks you do queue j = 0, 1, 2, ... in order: chunk j
// goes to stream j mod streams (CUDA family) or to buffer slot j mod buffers
// (Metal). The tests check exactly these boundaries and this assignment.
#pragma once
#include <cstddef>
#include <vector>

// The CPU-side definition of the kernel's polynomial, for the driver's reference:
// p(x) = sum over k = 0..degree of a_k x^k, with a_k = 0.5 for even k and -0.25
// for odd k. The kernels compute the same thing in float by Horner's rule.
inline double polyCoefficient(int k) { return (k & 1) ? -0.25 : 0.5; }

enum class Order {
    Depth,     // chunk by chunk: copy in 0, kernel 0, copy out 0, copy in 1, ...
    Breadth    // all copies in, then all kernels, then all copies out
};

struct StagedJob {
    const float* hostIn;   // n floats in host memory, pinned or pageable (the driver decides)
    float* hostOut;        // n floats in host memory, same kind as hostIn
    float* d_in;           // n floats of device memory the driver allocated
    float* d_out;          // n floats of device memory the driver allocated
    int n;                 // at least 1
    int degree;            // passed on to launchPoly unchanged
};

// What the provided launchers saw, for the driver's structural tests.
struct PolyCall {
    const void* in;        // CUDA family: the input pointer given to launchPoly. Metal: the input MTLBuffer.
    const void* out;       // the same for the output
    long long inOffset;    // Metal: the byte offsets given to encodePoly. CUDA family: 0 (the pointer
    long long outOffset;   //   carries the offset)
    int count;             // elements
    int degree;
    const void* stream;    // CUDA family: the stream (nullptr is the default stream). Metal: nullptr.
    int waitsBefore;       // Metal: waitFor calls made before this encodePoly. CUDA family: -1.
    double hostTime;       // Metal: host time, in seconds of mach time, when encodePoly was called. Else -1.
    const char* refused;   // nullptr, or why the provided launcher refused the call (nothing was launched)
};
struct PolyRecord {
    std::vector<PolyCall> calls;   // in the order they were made
    int waits = -1;                // Metal: waitFor calls. CUDA family: -1
    double gpuSeconds = -1;        // Metal: sum of GPUEndTime - GPUStartTime over those calls. Else -1
    std::vector<double> gpuStart, gpuEnd;   // Metal: each waited command buffer's GPU interval (mach seconds)
};
const PolyRecord& polyRecord();
void polyResetRecord();

#if defined(__OBJC__)
// ---- Metal: provided in launch.mm ----
#import <Metal/Metal.h>

struct MetalJob {
    id<MTLDevice> device;
    id<MTLCommandQueue> queue;
    const float* hostIn;   // n floats in ordinary memory the driver owns
    float* hostOut;        // n floats in ordinary memory the driver owns
    int n;                 // at least 1
    int degree;            // passed on to encodePoly unchanged
};

// Encodes poly_kernel (kernel.metal) over `count` elements into an open compute
// encoder: out[i] = p(in[i]) for the floats starting at the given byte offsets.
// Refuses (prints, records, encodes nothing) a count below 1, an offset that is
// not a multiple of 4, or a range past the end of a buffer.
void encodePoly(id<MTLComputeCommandEncoder> encoder, id<MTLBuffer> inBuf, NSUInteger inOffset,
                id<MTLBuffer> outBuf, NSUInteger outOffset, int count, int degree);
// Waits for a committed command buffer. Returns 0, or prints why the GPU did not
// run it and returns 1. Adds its GPU time and interval to the record.
int waitFor(id<MTLCommandBuffer> commandBuffer);
// A shared buffer of at least `bytes` bytes for slot `slot` (0 to 63), `which` 0
// for the slot's input and 1 for its output, or nil after printing why. The same
// slot and kind give the same buffer from one call to the next, made again only
// when a longer one is asked for, as the CUDA driver keeps d_in and d_out. A
// buffer made inside a timed call would charge that call for the first touch of
// every page (README.md, "Reading the output").
id<MTLBuffer> slotBuffer(id<MTLDevice> device, int slot, int which, NSUInteger bytes);
// The baseline: the whole array in one command buffer. Fill, kernel, drain.
int runSerialMetal(const MetalJob& job);
// ---- Metal: yours, in launch.mm. Returns 0, or 1 after printing what failed. ----
int runInFlight(const MetalJob& job, int buffers, int chunks);
#else
// ---- CUDA, HIP and the emulator: provided in kernel.cu ----
// (Declared only where cudaStream_t exists: the .cu files, built by nvcc, by HIP,
// for the emulator, or by the front-end check. main.cpp does not launch.)
#if defined(__CUDACC__) || defined(__HIPCC__) || defined(__HIP__) || defined(PMPP_EMU) || defined(PMPP_CUDA_FRONTEND_CHECK)
// Queues polyKernel over `count` elements in `stream`: d_out[i] = p(d_in[i]).
// Returns 0 once the launch is queued (a launch does not report its own errors:
// check cudaGetLastError() after it), or 1 after printing why it refused: a count
// below 1, which would be a grid of zero blocks.
int launchPoly(const float* d_in, float* d_out, int count, int degree, cudaStream_t stream);
#endif
// The baseline, the chapter 2 way: one cudaMemcpy in, one launch in the default
// stream, one cudaMemcpy out. Returns 0, or 1 after printing a checked error.
int runSerial(const StagedJob& job);
// ---- yours, in kernel.cu. Returns 0, or 1 after printing a checked error. ----
int runStaged(const StagedJob& job, int streams, int chunks, Order order);

// ---- provided in probe.cu: instruments for the driver ----
// asyncEngineCount and concurrentKernels from the device properties, or -1 on
// the emulator, which has neither field.
void probeEngines(int* asyncEngines, int* concurrentKernels);
// Page-locked host memory (cudaMallocHost), or nullptr after printing an error.
float* pinnedAlloc(size_t floats);
void pinnedFree(float* p);
// Best of `reps` timed runs after one untimed warm-up, each timed with events in
// the default stream: cudaMemcpy of the whole hostIn into d_in, launchPoly over
// all n at `degree`, cudaMemcpy of the whole d_out into hostOut. Returns 0, or 1
// after printing a checked error.
int probeCopyIn(const StagedJob& job, int reps, double* seconds);
int probeKernel(const StagedJob& job, int degree, int reps, double* seconds);
int probeCopyOut(const StagedJob& job, int reps, double* seconds);
#endif
